import * as THREE from 'three/webgpu';
import { texture, uv, vec2, vec3, vec4, mix, float, fract, sin, dot } from 'three/tsl';

export default function createNode(config, ctx) {
    const group = new THREE.Group();

    // Extract configuration with fallbacks
    const colors = config.visual?.colors || {
        ink: '#16161d',
        paper: '#e8ecf2',
        accent: '#ff2a38',
        surface: '#0b0b10'
    };

    const position = config.scenePosition?.position || [3.2, 1, 0.06];
    const rotation = config.scenePosition?.rotation || [0, 0, 0];
    const scale = config.scenePosition?.scale || [1, 1, 1];

    // Atlas region
    const atlasRect = config.atlas?.rect || [0, 0, 512, 320];
    const srcW = atlasRect[2] || 512;
    const srcH = atlasRect[3] || 320;
    const aspectRatio = srcW / srcH;

    // Plane dimensions
    const planeWidth = 1.6;
    const planeHeight = planeWidth / aspectRatio;

    // Load texture
    const imageUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/feature-card.png';
    const mapTexture = ctx.textureLoader(imageUrl);
    mapTexture.colorSpace = THREE.SRGBColorSpace;

    // Create geometry
    const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

    // Create material with TSL nodes
    const material = new THREE.MeshBasicNodeMaterial({
        transparent: true
    });

    // TSL: sample texture
    const texSample = texture(mapTexture);

    // Surface color for gradient
    const surfaceColor = new THREE.Color(colors.surface);
    const surfaceVec = vec3(float(surfaceColor.r), float(surfaceColor.g), float(surfaceColor.b));

    // Engineered gradient: darken toward bottom
    const gradientT = uv().y.oneMinus().mul(0.4);
    const gradientBlended = mix(texSample.rgb, surfaceVec, gradientT);

    // Subtle grain
    const grainScale = vec2(float(800.0), float(500.0));
    const grainUv = uv().mul(grainScale);
    const grainHash = fract(sin(dot(grainUv, vec2(float(12.9898), float(78.233)))).mul(float(43758.5453)));
    const grainAmount = grainHash.sub(float(0.5)).mul(float(0.035));
    const grainedColor = gradientBlended.add(vec3(grainAmount));

    // Set color node
    material.colorNode = vec4(grainedColor, texSample.a);

    // Create plane mesh
    const plane = new THREE.Mesh(geometry, material);
    group.add(plane);

    // Create MSDF text
    const textContent = config.textContent;
    let textStr = 'Collection 3';
    let textWeight = 400;

    if (typeof textContent === 'string') {
        textStr = textContent;
    } else if (textContent) {
        textStr = textContent.text || textContent.value || 'Collection 3';
        textWeight = textContent.fontWeight || textContent.weight || 400;
    }

    // Headline scale from design tokens
    const textSize = 0.34;
    const textColor = new THREE.Color(colors.paper);

    let textMesh = null;
    if (ctx.fontAtlas) {
        // Try common API methods
        const textConfig = {
            text: textStr,
            font: 'Lora',
            weight: textWeight,
            size: textSize,
            color: textColor,
            align: 'center',
            letterSpacing: 0.0
        };

        if (typeof ctx.fontAtlas.createText === 'function') {
            textMesh = ctx.fontAtlas.createText(textConfig);
        } else if (typeof ctx.fontAtlas.build === 'function') {
            textMesh = ctx.fontAtlas.build(textConfig);
        } else if (typeof ctx.fontAtlas.create === 'function') {
            textMesh = ctx.fontAtlas.create(textConfig);
        }
    }

    if (textMesh) {
        textMesh.position.set(0, -planeHeight * 0.3, 0.002);
        group.add(textMesh);
    }

    // Apply scene placement
    group.position.set(position[0], position[1], position[2]);
    group.rotation.set(rotation[0], rotation[1], rotation[2]);
    group.scale.set(scale[0], scale[1], scale[2]);

    // No cinematic primitives to apply (config.cinematicPrimitives is empty)

    // Event handlers (none specified)
    group.userData.handlers = {};

    // Cleanup
    const disposables = [geometry, material];
    group.userData.cleanup = () => {
        disposables.forEach(d => d.dispose());
        if (mapTexture && mapTexture.dispose) mapTexture.dispose();
        if (textMesh && textMesh.userData && textMesh.userData.cleanup) {
            textMesh.userData.cleanup();
        }
    };

    return group;
}
